  if [ -f "$PREFIX/VERSION" ]; then echo "ë²„ì „(ì„¤ì¹˜ë¨)   : $(cat "$PREFIX/VERSION")"; else echo "ì„¤ì¹˜ë¨        : ì•„ë‹ˆì˜¤ ($PREFIX ì—†ìŒ)"; fi
