  case "$PREFIX" in /|/opt|/usr|/etc|/root|/home|"") die "ì„¤ì¹˜ í´ë” ê²½ë¡œê°€ ìœ„í—˜í•´ ì‚­ì œí•˜ì§€ ì•ŠìŠµë‹ˆë‹¤: $PREFIX" ;; esac
  [ -f "$PREFIX/server.py" ] || [ -f "$PREFIX/data/fs_agent.db" ] || [ -f "$PREFIX/config.json" ] \
